import{c as a,Q as e,j as r,m as d}from"./chunks/framework.BXc4yaFE.js";const u=JSON.parse('{"title":"Claude Fable 5 與 Mythos 5 完整指南","description":"","frontmatter":{},"headers":[],"relativePath":"research/best-practices/36-claude-fable-5.md","filePath":"research/best-practices/36-claude-fable-5.md","lastUpdated":1785909234000}'),o={name:"research/best-practices/36-claude-fable-5.md"};function s(l,t,n,i,h,c){return e(),r("div",null,[...t[0]||(t[0]=[d(`<h1 id="claude-fable-5-與-mythos-5-完整指南" tabindex="-1">Claude Fable 5 與 Mythos 5 完整指南 <a class="header-anchor" href="#claude-fable-5-與-mythos-5-完整指南" aria-label="Permalink to &quot;Claude Fable 5 與 Mythos 5 完整指南&quot;">​</a></h1><blockquote><p>來源：<a href="https://www.anthropic.com/news/claude-fable-5-mythos-5" target="_blank" rel="noreferrer">Claude Fable 5 and Claude Mythos 5</a>（2026-06-09）<br> 來源：<a href="https://platform.claude.com/docs/en/about-claude/models/introducing-claude-fable-5-and-claude-mythos-5" target="_blank" rel="noreferrer">Introducing Claude Fable 5 and Claude Mythos 5</a><br> 來源：<a href="https://platform.claude.com/docs/en/build-with-claude/prompt-engineering/prompting-claude-fable-5" target="_blank" rel="noreferrer">Prompting Claude Fable 5</a><br> 整理日期：2026-06-15</p></blockquote><hr><h2 id="模型定位" tabindex="-1">模型定位 <a class="header-anchor" href="#模型定位" aria-label="Permalink to &quot;模型定位&quot;">​</a></h2><p><strong>Claude Fable 5</strong> 是 Anthropic 目前公開可用的最強模型，為 Mythos-class 模型加上安全分類器後的普及版本。</p><p><strong>Claude Mythos 5</strong> 與 Fable 5 共用同一底層模型，但安全分類器在特定領域寬鬆——僅限 Project Glasswing 受邀客戶使用。</p><hr><h2 id="技術規格" tabindex="-1">技術規格 <a class="header-anchor" href="#技術規格" aria-label="Permalink to &quot;技術規格&quot;">​</a></h2><table tabindex="0"><thead><tr><th>規格</th><th>值</th></tr></thead><tbody><tr><td>Model ID</td><td><code>claude-fable-5</code> / <code>claude-mythos-5</code></td></tr><tr><td>Context window</td><td>1M token（預設）</td></tr><tr><td>最大輸出 token</td><td>128k per request</td></tr><tr><td>輸入定價</td><td>$10 / MTok</td></tr><tr><td>輸出定價</td><td>$50 / MTok</td></tr><tr><td>發布日期</td><td>2026-06-09</td></tr></tbody></table><p><strong>可用平台</strong>：Claude API、Claude Platform on AWS、Amazon Bedrock、Vertex AI、Microsoft Foundry</p><hr><h2 id="訂閱方案訪問" tabindex="-1">訂閱方案訪問 <a class="header-anchor" href="#訂閱方案訪問" aria-label="Permalink to &quot;訂閱方案訪問&quot;">​</a></h2><table tabindex="0"><thead><tr><th>期間</th><th>行為</th></tr></thead><tbody><tr><td>2026-06-09 ~ 06-22（已到期）</td><td>包含於 Pro/Max/Team/Enterprise 訂閱方案額度中（不額外收費）</td></tr><tr><td>2026-06-23 起（<strong>現況</strong>）</td><td>需使用 Usage Credits（以 API 費率計費）</td></tr><tr><td>Opus 4.8 / Sonnet 4.5 / Haiku 3.5</td><td>仍包含於 Max 方案，不額外計費</td></tr></tbody></table><hr><h2 id="安全分類器-fable-5-特有" tabindex="-1">安全分類器（Fable 5 特有） <a class="header-anchor" href="#安全分類器-fable-5-特有" aria-label="Permalink to &quot;安全分類器（Fable 5 特有）&quot;">​</a></h2><p>Fable 5 有自動路由機制——當請求觸及以下領域時，自動切換至 Claude Opus 4.8 回應：</p><ul><li><strong>Cybersecurity</strong>（漏洞利用、惡意程式）</li><li><strong>Biology &amp; Chemistry</strong>（危害性合成）</li><li><strong>Distillation</strong>（模型提取）</li></ul><p>平均觸發率 &lt; 5% 的 sessions。用戶會看到模型切換通知。</p><hr><h2 id="基準測試表現" tabindex="-1">基準測試表現 <a class="header-anchor" href="#基準測試表現" aria-label="Permalink to &quot;基準測試表現&quot;">​</a></h2><table tabindex="0"><thead><tr><th>評測</th><th>結果</th></tr></thead><tbody><tr><td><strong>ViBench</strong>（vibe-coding 端到端）</td><td>最高分</td></tr><tr><td><strong>FrontierBench</strong>（Cognition 前沿 coding eval）</td><td>最高分</td></tr><tr><td><strong>Analytics benchmark</strong>（複雜長時分析任務）</td><td>首次突破 90%（比 Opus 4.8 高 10 分）</td></tr><tr><td><strong>Spreadsheet suite</strong></td><td>每個 effort 等級均優於 Opus 4.8，且速度快 25–30%</td></tr><tr><td><strong>SWE-bench</strong></td><td>SOTA（軟體工程整體）</td></tr></tbody></table><hr><h2 id="與-opus-4-8-的行為差異" tabindex="-1">與 Opus 4.8 的行為差異 <a class="header-anchor" href="#與-opus-4-8-的行為差異" aria-label="Permalink to &quot;與 Opus 4.8 的行為差異&quot;">​</a></h2><h3 id="_1-主動稽核" tabindex="-1">1. 主動稽核 <a class="header-anchor" href="#_1-主動稽核" aria-label="Permalink to &quot;1. 主動稽核&quot;">​</a></h3><p>Fable 5 長時間自主執行時容易產生「幻想進度」。需在 prompt 中明確要求：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>在回報進度前，請逐一對照本 session 的工具結果稽核每項聲明，</span></span>
<span class="line"><span>只回報有工具輸出為憑的工作；未驗證的項目請明確標示「待確認」。</span></span></code></pre></div><h3 id="_2-subagent-委派更積極" tabindex="-1">2. Subagent 委派更積極 <a class="header-anchor" href="#_2-subagent-委派更積極" aria-label="Permalink to &quot;2. Subagent 委派更積極&quot;">​</a></h3><p>Fable 5 比以往模型更主動派發平行 subagent。需在 prompt 中明確定義委派時機，並優先使用非同步通訊（orchestrator 不阻塞等待每個 subagent 返回）。</p><h3 id="_3-記憶與學習" tabindex="-1">3. 記憶與學習 <a class="header-anchor" href="#_3-記憶與學習" aria-label="Permalink to &quot;3. 記憶與學習&quot;">​</a></h3><p>Fable 5 能充分利用跨 session 的經驗紀錄。建議提供學習記錄位置（如 Markdown 檔案），每條記錄：</p><ul><li>一行標題摘要</li><li>校正內容或已確認的方法</li></ul><h3 id="_4-說明問題-vs-請求變更" tabindex="-1">4. 說明問題 vs 請求變更 <a class="header-anchor" href="#_4-說明問題-vs-請求變更" aria-label="Permalink to &quot;4. 說明問題 vs 請求變更&quot;">​</a></h3><p>Fable 5 需要明確的行為分類器。建議在 system prompt 加入：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>當用戶是在描述問題、提問或思考方向，而非請求實際變更時，</span></span>
<span class="line"><span>你的輸出應是評估意見（assessment），而非程式碼變更。</span></span></code></pre></div><hr><h2 id="prompt-caching-注意事項" tabindex="-1">Prompt Caching 注意事項 <a class="header-anchor" href="#prompt-caching-注意事項" aria-label="Permalink to &quot;Prompt Caching 注意事項&quot;">​</a></h2><ul><li>Fable 5 的快取與 Opus 4.8 的快取<strong>不相容</strong>（各自獨立）</li><li>若從 Opus 4.8 遷移至 Fable 5，<strong>整個快取需重建</strong></li><li>Mid-session 不可切換模型（快取失效）</li><li>Fable 5 安全分類器路由至 Opus 4.8 的 session 也不共享快取</li></ul><hr><h2 id="模型選擇建議-對照-opus-4-8" tabindex="-1">模型選擇建議（對照 Opus 4.8） <a class="header-anchor" href="#模型選擇建議-對照-opus-4-8" aria-label="Permalink to &quot;模型選擇建議（對照 Opus 4.8）&quot;">​</a></h2><table tabindex="0"><thead><tr><th>情境</th><th>推薦模型</th></tr></thead><tbody><tr><td>複雜長時間 coding 任務（codebase 遷移、全 audit）</td><td><strong>Fable 5</strong></td></tr><tr><td>Vibe-coding / 試作 / 端到端自主任務</td><td><strong>Fable 5</strong></td></tr><tr><td>需要長時間分析或試算表作業</td><td><strong>Fable 5</strong>（快 25-30%）</td></tr><tr><td>涉及 cybersecurity / bio-chem 主題</td><td><strong>Opus 4.8</strong>（直接指定，避免自動路由）</td></tr><tr><td>預算敏感的 batch 處理</td><td><strong>Opus 4.8 / Sonnet 4.6</strong></td></tr><tr><td>Fast mode 低延遲</td><td><strong>Fable 5</strong>（$10/$50 同價，約 Opus 4.8 standard 2.5× 速）</td></tr></tbody></table><hr><h2 id="延伸閱讀" tabindex="-1">延伸閱讀 <a class="header-anchor" href="#延伸閱讀" aria-label="Permalink to &quot;延伸閱讀&quot;">​</a></h2><ul><li><code>05-claude-prompting-best-practices.md</code> — Effort 等級、XML 標籤、Agentic 系統設計</li><li><code>32-dynamic-workflows.md</code> — Fable 5 原生支援 dynamic workflow</li><li><code>04-subagent-mcp-skill.md</code> — Subagent 委派策略（Fable 5 更積極委派）</li></ul>`,43)])])}const p=a(o,[["render",s]]);export{u as __pageData,p as default};
